package generated;

import com.openjiuwen.core.foundation.tool.Tool;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

public final class WealthQueryTool extends Tool {
  private static final String BALANCE_TOOL = "get_account_balance";
  private static final String PRODUCTS_TOOL = "list_wealth_products";

  private final Tool transport;

  public WealthQueryTool(Tool transport) {
    super(Objects.requireNonNull(transport, "transport").getCard());
    this.transport = transport;
  }

  @Override protected Object invokeInternal(Map<String,Object> inputs, Map<String,Object> kwargs) throws Exception {
    String toolName = getCard() == null ? null : getCard().getName();
    if (BALANCE_TOOL.equals(toolName)) return invokeBalance(inputs, kwargs);
    if (PRODUCTS_TOOL.equals(toolName)) return invokeProducts(inputs, kwargs);
    throw new IllegalArgumentException("TOOL_NAME_UNSUPPORTED");
  }

  private Object invokeBalance(Map<String,Object> inputs, Map<String,Object> kwargs) throws Exception {
    if (inputs == null || !Set.of("accountId").equals(inputs.keySet())) throw invalidInput();
    Object accountId = inputs.get("accountId");
    if (!(accountId instanceof String) || ((String) accountId).trim().isEmpty()) throw invalidInput();

    Object response = transport.invoke(Map.of("accountId", accountId), kwargs);
    if (!(response instanceof Map)) throw invalidResponse();
    Map<?,?> raw = (Map<?,?>) response;

    Object responseAccountId = raw.get("accountId");
    Object currency = raw.get("currency");
    Object availableBalanceFen = raw.get("availableBalanceFen");
    Object asOf = raw.get("asOf");
    if (!(responseAccountId instanceof String)
        || !(currency instanceof String)
        || !(asOf instanceof String)
        || !(availableBalanceFen instanceof Integer || availableBalanceFen instanceof Long)) {
      throw invalidResponse();
    }

    Map<String,Object> result = new LinkedHashMap<>();
    result.put("accountId", responseAccountId);
    result.put("currency", currency);
    result.put("availableBalanceFen", availableBalanceFen);
    result.put("asOf", asOf);
    return result;
  }

  private Object invokeProducts(Map<String,Object> inputs, Map<String,Object> kwargs) throws Exception {
    if (inputs == null || !inputs.isEmpty()) throw invalidInput();

    Object response = transport.invoke(Map.of(), kwargs);
    if (!(response instanceof Map)) throw invalidResponse();
    Map<?,?> raw = (Map<?,?>) response;

    Object items = raw.get("items");
    Object version = raw.get("version");
    if (!(items instanceof List) || !(version instanceof String)) throw invalidResponse();

    for (Object entry : (List<?>) items) {
      if (!(entry instanceof Map)) throw invalidResponse();
      Map<?,?> item = (Map<?,?>) entry;
      Object minimumAmountFen = item.get("minimumAmountFen");
      if (!(item.get("productId") instanceof String)
          || !(item.get("name") instanceof String)
          || !(item.get("status") instanceof String)
          || !(item.get("description") instanceof String)
          || !(minimumAmountFen instanceof Integer || minimumAmountFen instanceof Long)) {
        throw invalidResponse();
      }
    }

    Map<String,Object> result = new LinkedHashMap<>();
    result.put("items", items);
    result.put("version", version);
    return result;
  }

  private static IllegalArgumentException invalidInput() {
    return new IllegalArgumentException("TOOL_INPUT_CONTRACT_INVALID");
  }

  private static IllegalStateException invalidResponse() {
    return new IllegalStateException("TOOL_RESPONSE_CONTRACT_INVALID");
  }
}
